// 8 bytes a row, little end first; where a row holds NULL its bit of nulls is
// set, and its value is 0 among integers and a NaN among reals, which SQLite
// keeps none of. Any other column goes as values: text, blobs, and INTEGERs
// beside REALs, neither read as the other.
type SqlColumn struct {
	Name string `wire:"1,name"`
	// an int64 a row
	Integers *[]byte `wire:"2,integers"`
	// a float64 a row
	Reals *[]byte `wire:"3,reals"`
	// a bit a row, a byte's lowest first, set where the row holds NULL; absent when none does
	Nulls  *[]byte `wire:"4,nulls"`
	Values *[]Cell `wire:"5,values"`
}

func (m SqlColumn) Write(w *Writer) {
	head := w.OpenMap()
	n := 0
	if m.Name != "" {
		w.Uint(1)
		w.Str(m.Name)
		n++
	}
	if m.Integers != nil {
		w.Uint(2)
		w.Bin(*m.Integers)
		n++
	}
	if m.Reals != nil {
		w.Uint(3)
		w.Bin(*m.Reals)
		n++
	}
	if m.Nulls != nil {
		w.Uint(4)
		w.Bin(*m.Nulls)
		n++
	}
	if m.Values != nil {
		w.Uint(5)
		w.Array(len(*m.Values))
		for _, item0 := range *m.Values {
			w.Cell(item0)
		}
		n++
	}
	w.CloseMap(head, n)
}

func (m *SqlColumn) Read(r *Reader) {
	*m = SqlColumn{}
	var seen Seen
	for n := r.Map(); n > 0; n-- {
		switch r.Field(&seen) {
		case 1:
			m.Name = r.Str()
		case 2:
			v := r.Bin()
			m.Integers = &v
		case 3:
			v := r.Bin()
			m.Reals = &v
		case 4:
			v := r.Bin()
			m.Nulls = &v
		case 5:
			v := []Cell{}
			for k0 := r.Array(); k0 > 0; k0-- {
				item0 := r.Cell()
				v = append(v, item0)
			}
			r.Leave()
			m.Values = &v
		default:
			r.Skip()
		}
	}
	r.Leave()
}

// IsZero says whether SqlColumn writes as no field at all.
func (m SqlColumn) IsZero() bool {
	return m.Name == "" &&
		m.Integers == nil &&
		m.Reals == nil &&
		m.Nulls == nil &&
		m.Values == nil
}

// SqlColumns is the schema's sql.Columns.
//
// Rows a statement gave, by their columns, a part of them a message: every
// part holds every column, in the statement's order and as the same one of
// three, for the same rows.
