// SqlTxCall is the schema's sql.TxCall.
//
// A transaction's call, or its end: the last DATA commits, or not. A call is
// a statement, or a call of kv or jobs on a bucket or a queue kept in the
// database's file: a method of theirs with its request, kv.set or jobs.add,
// which runs in the transaction.
type SqlTxCall struct {
	Text   string `wire:"1,text"`
	Values []Cell `wire:"2,values"`
	// all, one, scalar or exec; call for a method; nothing in the last
	Want string `wire:"3,want"`
	// in the last: true commits, false rolls back
	Commit bool `wire:"4,commit"`
	// with want call: the method, its request in body
	Method *uint64 `wire:"5,method"`
	Body   *[]byte `wire:"6,body"`
}

func (m SqlTxCall) Write(w *Writer) {
	head := w.OpenMap()
	n := 0
	if m.Text != "" {
		w.Uint(1)
		w.Str(m.Text)
		n++
	}
	if len(m.Values) > 0 {
		w.Uint(2)
		w.Array(len(m.Values))
		for _, item0 := range m.Values {
			w.Cell(item0)
		}
		n++
	}
	if m.Want != "" {
		w.Uint(3)
		w.Str(m.Want)
		n++
	}
	if m.Commit {
		w.Uint(4)
		w.Bool(m.Commit)
		n++
	}
	if m.Method != nil {
		w.Uint(5)
		w.Uint(*m.Method)
		n++
	}
	if m.Body != nil {
		w.Uint(6)
		w.Bin(*m.Body)
		n++
	}
	w.CloseMap(head, n)
}

func (m *SqlTxCall) Read(r *Reader) {
	*m = SqlTxCall{}
	var seen Seen
	for n := r.Map(); n > 0; n-- {
		switch r.Field(&seen) {
		case 1:
			m.Text = r.Str()
		case 2:
			v := []Cell{}
			for k0 := r.Array(); k0 > 0; k0-- {
				item0 := r.Cell()
				v = append(v, item0)
			}
			r.Leave()
			m.Values = v
		case 3:
			m.Want = r.Str()
		case 4:
			m.Commit = r.Bool()
		case 5:
			v := r.Uint()
			m.Method = &v
		case 6:
			v := r.Bin()
			m.Body = &v
		default:
			r.Skip()
		}
	}
	r.Leave()
}

// IsZero says whether SqlTxCall writes as no field at all.
func (m SqlTxCall) IsZero() bool {
	return m.Text == "" &&
		len(m.Values) == 0 &&
		m.Want == "" &&
		!m.Commit &&
		m.Method == nil &&
		m.Body == nil
}

// SqlTxAnswer is the schema's sql.TxAnswer.
//
// A call's answer: its rows, what it changed, a method's answer, or why it
// failed, which leaves the transaction as it was before the call.
type SqlTxAnswer struct {
	Rows    *SqlRows `wire:"1,rows"`
	Done    *SqlDone `wire:"2,done"`
	Failure *Failure `wire:"3,failure"`
	// what a method answered, as its own answer
	Body *[]byte `wire:"4,body"`
}

func (m SqlTxAnswer) Write(w *Writer) {
	head := w.OpenMap()
	n := 0
	if m.Rows != nil {
		w.Uint(1)
		m.Rows.Write(w)
		n++
	}
	if m.Done != nil {
		w.Uint(2)
		m.Done.Write(w)
		n++
	}
	if m.Failure != nil {
		w.Uint(3)
		m.Failure.Write(w)
		n++
	}
	if m.Body != nil {
		w.Uint(4)
		w.Bin(*m.Body)
		n++
	}
	w.CloseMap(head, n)
}

func (m *SqlTxAnswer) Read(r *Reader) {
	*m = SqlTxAnswer{}
	var seen Seen
	for n := r.Map(); n > 0; n-- {
		switch r.Field(&seen) {
		case 1:
			var v SqlRows
			v.Read(r)
			m.Rows = &v
		case 2:
			var v SqlDone
			v.Read(r)
			m.Done = &v
		case 3:
			var v Failure
			v.Read(r)
			m.Failure = &v
		case 4:
			v := r.Bin()
			m.Body = &v
		default:
			r.Skip()
		}
	}
	r.Leave()
}

// IsZero says whether SqlTxAnswer writes as no field at all.
func (m SqlTxAnswer) IsZero() bool {
	return m.Rows == nil &&
		m.Done == nil &&
		m.Failure == nil &&
		m.Body == nil
}
